// src/components/AiCompanion.js
import React, { useState } from 'react';
import styled from 'styled-components';

const CompanionContainer = styled.div`
  margin: 20px 0;
  padding: 20px;
  border-radius: 8px;
  background-color: #e0f7fa;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  max-width: 400px;
`;

const Message = styled.p`
  font-size: 1.2rem;
  margin-bottom: 15px;
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 10px;
`;

const Button = styled.button`
  flex: 1;
  padding: 12px;
  border-radius: 5px;
  border: none;
  cursor: pointer;

  ${({ yes }) =>
    yes
      ? `background-color: #4caf50; color: white;`
      : `background-color: #f44336; color: white;`}

  &:hover {
    opacity: 0.9;
  }
`;

const RecommendationList = styled.ul`
  margin-top: 10px;
  list-style: none;
  padding: 0;
`;

const RecommendationItem = styled.li`
  display: flex;
  justify-content: space-between;
  margin: 5px 0;
  padding: 10px;
  background-color: #f1f8e9;
  border-radius: 5px;
  border: 1px solid #c8e6c9;
`;

const AiCompanion = ({ setPackagePrice, handleSelect }) => {
  const [step, setStep] = useState(0);
  const [recommendations, setRecommendations] = useState([]);

  const questions = [
    'Are you preparing for your first triathlon?',
    'Do you need a complete gear package?',
    'Do you prefer entry-level or advanced equipment?',
    'Do you have a specific budget in mind?',
  ];

  const handleYes = () => {
    const nextStep = step + 1;

    if (step === 3) {
      const userBudget = prompt('Enter your budget (in USD):');
      setPackagePrice(userBudget);
      generateRecommendations(userBudget);
    }

    setStep(nextStep);
  };

  const handleNo = () => setStep((prev) => prev + 1);

  const generateRecommendations = (budget) => {
    const mockItems = [
      { id: 1, Name: 'Basic Road Bike', Price: 600 },
      { id: 2, Name: 'Helmet', Price: 100 },
    ]; // Example items for demo
    const filtered = mockItems.filter((item) => item.Price <= budget);
    setRecommendations(filtered);
  };

  return (
    <CompanionContainer>
      {step < questions.length ? (
        <>
          <Message>{questions[step]}</Message>
          <ButtonGroup>
            <Button yes onClick={handleYes}>Yes</Button>
            <Button onClick={handleNo}>No</Button>
          </ButtonGroup>
        </>
      ) : (
        <>
          <h3>Recommended Items</h3>
          <RecommendationList>
            {recommendations.map((item) => (
              <RecommendationItem key={item.id}>
                <span>{item.Name}</span>
                <button onClick={() => handleSelect(item)}>Add</button>
              </RecommendationItem>
            ))}
          </RecommendationList>
        </>
      )}
    </CompanionContainer>
  );
};

export default AiCompanion;
